// Lê o CSV (texto) vindo do HTTP Request e converte em lista de investimentos
const bruto = $json.data ?? $json.body ?? '';
if (typeof bruto !== 'string' || !bruto.trim()) {
  throw new Error('O CSV não veio como texto. Confira o HTTP Request (Response Format = Text).');
}

const normaliza = (s) =>
  String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();

const paraNumero = (v) => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').replace(/[^\d.,-]/g, '');
  if (s.includes(',') && s.includes('.')) s = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',')) s = s.replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  return Number(s) || 0;
};

// Parser de linha que respeita campos entre aspas (ex.: "10,5% a.a.")
const parseLinha = (linha) => {
  const cols = [];
  let atual = '';
  let aspas = false;
  for (let i = 0; i < linha.length; i++) {
    const ch = linha[i];
    if (ch === '"') {
      if (aspas && linha[i + 1] === '"') { atual += '"'; i++; }
      else aspas = !aspas;
    } else if (ch === ',' && !aspas) {
      cols.push(atual.trim());
      atual = '';
    } else {
      atual += ch;
    }
  }
  cols.push(atual.trim());
  return cols;
};

const linhas = bruto.replace(/^\uFEFF/, '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
const headers = parseLinha(linhas[0]).map(normaliza);

const investimentos = linhas.slice(1).map((linha) => {
  const cols = parseLinha(linha);
  const obj = {};
  headers.forEach((h, i) => { obj[h] = cols[i] ?? ''; });
  obj.minimo = paraNumero(obj.minimo);
  return obj;
});

return [{ json: { investimentos } }];

const entrada = $input.first().json;
const investimentos = entrada.investimentos ?? [];
const webhook = $('Webhook').first()?.json ?? {};
const clientes = webhook.body?.clientes ?? entrada.body?.clientes ?? entrada.clientes ?? [];

if (!Array.isArray(clientes) || clientes.length === 0) {
  throw new Error('Nenhum cliente recebido no webhook (esperado: body.clientes como lista).');
}

const normaliza = (s) =>
  String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();

// Aceita 1500, "1500.50", "1.500,50", "R$ 1.500,50"
const paraNumero = (v) => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').replace(/[^\d.,-]/g, '');
  if (s.includes(',') && s.includes('.')) s = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',')) s = s.replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  return Number(s) || 0;
};
const moeda = (n) =>
  'R$ ' + Number(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const sortear = (l) => l[Math.floor(Math.random() * l.length)];

const dicas = {
  conservador: 'Foco em segurança e liquidez.',
  moderado: 'Equilíbrio entre segurança e rentabilidade.',
  arrojado: 'Maior risco, maior potencial de retorno. Diversifique.',
};

return clientes.map((c) => {
  const saldo = paraNumero(c.saldo);
  const chave = normaliza(c.perfil);
  const doPerfil = investimentos
    .filter((i) => normaliza(i.perfil) === chave)
    .sort((a, b) => a.minimo - b.minimo);
  const possiveis = doPerfil.filter((i) => i.minimo <= saldo);

  const base = {
    nome: c.nome,
    email: c.email,
    perfil: c.perfil,
    saldo_texto: c.saldo,
    saldo_num: saldo,
  };

  if (!doPerfil.length) {
    return { json: { ...base, recomendacao: null, motivo: 'perfil_sem_produto', dica: '', mensagens: [],
      mensagem_escolhida: `Olá ${c.nome}! Não encontramos produtos para o perfil ${c.perfil}.` } };
  }

  const ok = possiveis.length > 0;
  const e = ok ? possiveis[possiveis.length - 1] : doPerfil[0];
  const p = `**${e.produto}**`;
  const min = moeda(e.minimo);
  const falta = moeda(e.minimo - saldo);

  const mensagens = ok ? [
    `Olá ${c.nome}! Pelo seu perfil (${c.perfil}), uma boa opção é ${p} (mínimo ${min}). Com seu saldo atual (${moeda(saldo)}), você já consegue investir. Rentabilidade: ${e.rentabilidade}.`,
    `Oi ${c.nome}! Recomendação para perfil ${c.perfil}: ${p} (mínimo ${min}). Seu saldo (${moeda(saldo)}) já atende o mínimo. Rentabilidade: ${e.rentabilidade}.`,
    `${c.nome}, indo direto ao ponto: para o perfil ${c.perfil}, ${p} (mínimo ${min}). Você tem ${moeda(saldo)}, então dá pra aplicar. Rentabilidade: ${e.rentabilidade}.`,
  ] : [
    `Olá ${c.nome}! Para o perfil ${c.perfil}, a opção mais acessível é ${p} (mínimo ${min}). Seu saldo é ${moeda(saldo)}, faltam ${falta}. Rentabilidade: ${e.rentabilidade}.`,
    `Oi ${c.nome}! ${p} exige ${min} e você tem ${moeda(saldo)} (faltam ${falta}). Rentabilidade: ${e.rentabilidade}.`,
    `${c.nome}, para o perfil ${c.perfil} o ideal seria ${p}, mínimo ${min}. Faltam ${falta}. Rentabilidade: ${e.rentabilidade}.`,
  ];

  return { json: {
    ...base,
    recomendacao: { perfil: e.perfil, produto: e.produto, minimo: e.minimo, rentabilidade: e.rentabilidade },
    motivo: ok ? 'saldo_ok' : 'saldo_insuficiente',
    dica: dicas[chave] ?? '',
    mensagens,
    mensagem_escolhida: sortear(mensagens),
  } };
});

