// Combina a resposta da IA (item i) com o cliente correspondente (item i do cruzamento).
// Se a IA falhar ou vier fora do formato, cai para a mensagem estática do MVP.
const clientes = $('Cruzar Perfil x Investimentos (MVP)').all();

const escapa = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const paraHtml = (s) => escapa(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\r?\n/g, '<br>');

return $input.all().map((item, i) => {
  const cliente = clientes[i]?.json ?? {};
  let assunto = 'Sua recomendação de investimento personalizada';
  let corpo = cliente.mensagem_escolhida ?? '';
  let origem = 'fallback_estatico';

  try {
    const texto = item.json?.choices?.[0]?.message?.content;
    const conteudo = JSON.parse(texto);
    if (conteudo.assunto && conteudo.corpo) {
      assunto = String(conteudo.assunto);
      corpo = String(conteudo.corpo);
      origem = 'ia';
    }
  } catch (e) {
    // fallback silencioso para a mensagem estática do MVP
  }

  return { json: {
    email: cliente.email ?? '',
    nome: cliente.nome ?? '',
    assunto,
    corpo: paraHtml(corpo),
    origem,
  } };
});

// Registra todos os itens que falharam (não só o primeiro)
const itens = $input.all().map((i) => i.json);
console.log('[ERRO] Falha no processamento:', JSON.stringify(itens));
const logged_at = new Date().toISOString();
return itens.map((item) => ({ json: { ...item, status: 'erro', logged_at } }));
